"use strict";
// The learned second opinion (port of film-scan-cleanup/scripts/learned.py): a small boosted-tree
// model trained on Magnus's answers. It reads only numbers the detector already measured, so the
// skill and the plugin share one model (learned_model.js is generated by train_model.py).
const MODEL = require("./learned_model").model;
// the soft step's own model (learned_soft_model.js, generated by train_soft_model.py)
let SOFT = null;
try { SOFT = require("./learned_soft_model").model; } catch (e) { SOFT = null; }
// ... and the one that decides whether a soft heal is picture (learned_soft_heal_model.js, same trainer): the same trees
// also fed Claude's visual labels of soft blobs on 49 scans he never answered. Without it, the soft model decides both.
let SOFT_HEAL = null;
try { SOFT_HEAL = require("./learned_soft_heal_model").model; } catch (e) { SOFT_HEAL = null; }

const NUM = ["z", "z_fine", "area", "width", "length", "pieces", "white", "sharp", "crisp", "core_y", "bg_y",
  "ring_range", "flat", "broad", "detail", "tex", "busy", "field",
  "elong", "plateau", "fine", "cosw", "near", "sim", "stronger", "net"];
const LINE = ["one_med", "one_frac", "hf", "dips", "straight", "per", "gaps", "half_w"];
const KINDS = ["hair/fibre", "dust", "speck", "soft"];

// rules the model never overrules, and the strength from which left-alone marks were asked about
const VETO = ["link texture", "rides along an edge", "ruler-straight", "runs with the strand texture",
  "one of", "grain marks on the film border"];
const FLOOR = { "hair/fibre": 10.0, dust: 10.0, speck: 9.0, soft: 12.0 };

const num = (v) => (typeof v === "number" ? v : NaN);

function features(m) {
  const f = NUM.map((k) => num(m[k]));
  const ln = m.line || {};
  for (const k of LINE) f.push(num(ln[k]));
  for (const k of KINDS) f.push(m.kind === k ? 1.0 : 0.0);
  const bg = m.bg;
  f.push(Array.isArray(bg) && bg.length ? bg.reduce((a, b) => a + b, 0) / bg.length : NaN);
  f.push(typeof m.area === "number" ? Math.log1p(m.area) : NaN);
  return f;
}

function tree(t, x) {
  while (t.leaf === undefined) {
    const v = x[t.f];
    t = (Number.isNaN(v) ? t.nl : v <= t.t) ? t.l : t.r;
  }
  return t.leaf;
}

// P(dust) for one mark
function probability(m) {
  const x = features(m);
  let F = MODEL.base;
  for (const t of MODEL.trees) F += MODEL.lr * tree(t, x);
  return 1 / (1 + Math.exp(-F));
}

// the soft judge's record -> the soft model's inputs (as learned.py's soft_features)
const SOFT_NUM = ["z", "area", "elong", "plateau", "fine", "cosw", "broad", "near", "sim", "stronger", "net"];
function softFeatures(r) {
  const f = SOFT_NUM.map((k) => num(r[k]));
  f.push(typeof r.area === "number" ? Math.log1p(r.area) : NaN);
  return f;
}

function softP(model, r) {
  const x = softFeatures(r);
  let F = model.base;
  for (const t of model.trees) F += model.lr * tree(t, x);
  return 1 / (1 + Math.exp(-F));
}

// P(dust) for one soft record, or null without a soft model: the decision that may turn a left blob into dust
function softProbability(r) {
  return SOFT ? softP(SOFT, r) : null;
}

// P(dust) for a soft blob the rules would heal: the decision that may turn the heal into photo
function softHealProbability(r) {
  return SOFT_HEAL ? softP(SOFT_HEAL, r) : softProbability(r);
}

// the soft rules the learned decision may overrule toward dust (his answers covered them). Not "long soft
// highlight" (elongated soft marks stay with the soft-fibre stage, which knows twigs, stems and strands)
// and not "in-focus detail beside it" (the earring / hair-edge rule)
const SOFT_OVERRULES = ["big soft patch", "one of many same-size blobs", "among many soft highlights"];

module.exports = { probability, features, VETO, FLOOR, softProbability, softHealProbability, softFeatures, SOFT_OVERRULES };
